const request = require('supertest');
const app = require('./app');

// Close the server after all tests
afterAll(() => {
  app.close();
});

describe('GET /users', () => {
  // Happy path test
  test('returns 200 and the list of users', async () => {
    const response = await request(app).get('/users');

    expect(response.status).toBe(200);
    expect(response.body).toBeInstanceOf(Array);
    expect(response.body.length).toBe(2);
    expect(response.body).toEqual([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  // Verify response format matches expected schema
  test('returns users with correct schema', async () => {
    const response = await request(app).get('/users');

    expect(response.status).toBe(200);

    const user = response.body[0];
    expect(user).toHaveProperty('id');
    expect(user).toHaveProperty('name');
    expect(user).toHaveProperty('email');

    expect(typeof user.id).toBe('number');
    expect(typeof user.name).toBe('string');
    expect(typeof user.email).toBe('string');

    expect(user.email).toMatch(/^[^@]+@[^@]+\\.[^@]+$/);
  });

  // Error handling test
  test('handles potential server errors gracefully', async () => {
    // Spy on console.error to ensure it's not called
    const consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

    // Test with an invalid route to ensure server doesn't crash
    const response = await request(app).get('/users/nonexistent');

    // The app doesn't have this route, so it should return 404
    expect(response.status).toBe(404);

    // Verify error wasn't logged (since 404 is expected)
    expect(consoleErrorSpy).not.toHaveBeenCalled();

    // Restore console.error
    consoleErrorSpy.mockRestore();
  });
});

