// Modify app.js to export the server instance
// We'll temporarily override app.listen to capture the server
const originalListen = require('express').Application.listen;

// Track the server instance
let serverInstance;

// Override listen to capture the server instance
require('express').Application.listen = function(...args) {
  serverInstance = originalListen.apply(this, args);
  return serverInstance;
};

// Require the app which will now capture the server instance
const app = require('./app');

// Restore the original listen method
require('express').Application.listen = originalListen;

// Close the server after all tests
afterAll((done) => {
  if (serverInstance) {
    serverInstance.close(() => {
      done();
    });
  } else {
    done();
  }
});

