const request = require('supertest');
const app = require('./app');

// Define the expected schema for user objects
const expectedUserSchema = {
  id: expect.any(Number),
  name: expect.any(String),
  email: expect.any(String),
};

// Helper function to validate array of users
const validateUsersResponse = (users) => {
  expect(Array.isArray(users)).toBe(true);
  expect(users.length).toBeGreaterThan(0);

  users.forEach(user => {
    expect(user).toEqual(expectedUserSchema);

    // Additional validation for email format
    const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;
    expect(emailRegex.test(user.email)).toBe(true);
  });
};

describe('GET /users', () => {
  it('should return 200 status and users array on successful request (happy path)', async () => {
    const response = await request(app)
      .get('/users')
      .expect('Content-Type', /json/)
      .expect(200);

    // Validate the response body format
    validateUsersResponse(response.body);

    // Check that we have the expected users
    expect(response.body.length).toBe(2);
    expect(response.body[0]).toEqual({
      id: 1,
      name: 'Alice',
      email: 'alice@example.com'
    });
    expect(response.body[1]).toEqual({
      id: 2,
      name: 'Bob',
      email: 'bob@example.com'
    });
  });

  it('should return users with correct response format', async () => {
    const response = await request(app).get('/users').expect(200);

    // Test the schema explicitly
    validateUsersResponse(response.body);
  });

  // Test error handling - currently the endpoint doesn't have error conditions,
  // but we can test unexpected server errors by mocking or simulating them
  it('should handle unexpected server errors', async () => {
    // Save the original users endpoint handler
    const originalGetUsers = app._router.stack.find(layer => 
      layer.route?.path === '/users' && layer.route?.methods.get
    );

    // Temporarily replace the route handler with one that throws an error
    app.get('/users', (req, res) => {
      throw new Error('Unexpected server error');
    });

    const response = await request(app)
      .get('/users')
      .expect('Content-Type', /json/);

    // Expect a 500 status code for server errors
    expect(response.status).toBe(500);

    // Restore the original handler
    if (originalGetUsers) {
      app._router.stack = app._router.stack.filter(layer => 
        layer.route?.path !== '/users' || !layer.route?.methods.get
      );
      app.get('/users', originalGetUsers.route.stack[0].handle);
    }
  });

  // Test query with error simulation using jest.spyOn
  it('should handle errors when fetching users', async () => {
    // Spy on console.error to prevent error output during tests
    const consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

    // Replace the route temporarily
    app._router.stack = app._router.stack.filter(layer => 
      layer.route?.path !== '/users' || !layer.route?.methods.get
    );

    app.get('/users', (req, res) => {
      res.status(500).json({ error: 'Internal Server Error' });
    });

    const response = await request(app).get('/users').expect(500);

    expect(response.body).toHaveProperty('error');
    expect(response.body.error).toBe('Internal Server Error');

    // Restore console.error
    consoleErrorSpy.mockRestore();

    // Re-create the original route
    app._router.stack = app._router.stack.filter(layer => 
      layer.route?.path !== '/users' || !layer.route?.methods.get
    );

    app.get('/users', (req, res) => {
      res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]);
    });
  });
});

