  });
  app.server = server;
} else {
  server = app.server;
}

// Helper function to make HTTP requests
function httpRequest(options, postData = null) {
  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        try {
          const jsonData = data ? JSON.parse(data) : null;
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: jsonData
          });
        } catch (err) {
          reject(new Error(`Failed to parse JSON: ${err.message}`));
        }
      });
    });

    req.on('error', (err) => {
      reject(err);
    });

    if (postData) {
      req.write(postData);
    }
    req.end();
  });
}

// Test 1: Happy path - should return 200 and users data
async function testHappyPath() {
  try {
    const response = await httpRequest({
      hostname: 'localhost',
      port: PORT,
      path: '/users',
      method: 'GET',
      headers: {
        'Content-Type': 'application/json'
      }
    });

    // Check status code
    assert.strictEqual(response.statusCode, 200, `Expected status code 200, got ${response.statusCode}`);

    // Check response body exists and is an array
    assert.ok(response.body, 'Response body should exist');
    assert.ok(Array.isArray(response.body), 'Response body should be an array');
    assert.ok(response.body.length > 0, 'Response body should not be empty');

    // Check first user structure
    const user = response.body[0];
    assert.ok('id' in user, 'User should have an id property');
    assert.ok('name' in user, 'User should have a name property');
    assert.ok('email' in user, 'User should have an email property');

    console.log('✓ Happy path test passed');
    return true;
  } catch (error) {
    console.error('✗ Happy path test failed:', error.message);
    return false;
  }
}

// Test 2: Response format/schema validation
async function testResponseSchema() {
  try {
    const response = await httpRequest({
      hostname: 'localhost',
      port: PORT,
      path: '/users',
      method: 'GET'
    });

    // Validate each user in the response
    response.body.forEach((user, index) => {
      // Check data types
      assert.strictEqual(typeof user.id, 'number', `User ${index} id should be a number`);
      assert.strictEqual(typeof user.name, 'string', `User ${index} name should be a string`);
      assert.strictEqual(typeof user.email, 'string', `User ${index} email should be a string`);

      // Check email format
      const emailRegex = /^[^@]+@[^@]+\.[^@]+$/;
      assert.ok(emailRegex.test(user.email), `User ${index} email format is invalid: ${user.email}`);
    });

    console.log('✓ Response schema test passed');
    return true;
  } catch (error) {
    console.error('✗ Response schema test failed:', error.message);
    return false;
  }
}

// Test 3: Error handling - test invalid path
async function testErrorHandling() {
  try {
    // Test a non-existent endpoint to ensure we can handle 404s
    const response404 = await httpRequest({
      hostname: 'localhost',
      port: PORT,
      path: '/nonexistent',
      method: 'GET'
    });

    // This should return 404, which is expected behavior
    assert.ok([404, 200].includes(response404.statusCode), `Expected 404 or 200 status code, got ${response404.statusCode}`);

    // The /users endpoint itself doesn't have error conditions in the current implementation,
    // but we can verify it doesn't throw errors for valid requests
    const response = await httpRequest({
      hostname: 'localhost',
      port: PORT,
      path: '/users',
      method: 'GET'
    });

    assert.strictEqual(response.statusCode, 200, `Expected 200 status code, got ${response.statusCode}`);

    console.log('✓ Error handling test passed');
    return true;
  } catch (error) {
    console.error('✗ Error handling test failed:', error.message);
    return false;
  }
}

// Run all tests
async function runTests() {
  try {
    // Add a small delay to ensure server is ready
    await new Promise(resolve => setTimeout(resolve, 100));

    const results = [];

    results.push(await testHappyPath());
    results.push(await testResponseSchema());
    results.push(await testErrorHandling());

    // Cleanup
    if (server) {
      server.close(() => {
        console.log('Server closed');
      });
    }

    // Report results
    const passed = results.filter(r => r).length;
    const total = results.length;

    console.log(`\nTests completed: ${passed}/${total} passed`);

    // Exit with appropriate code
    if (passed === total) {
      process.exit(0);
    } else {
      process.exit(1);
    }

  } catch (error) {
    console.error('Test runner failed:', error);
    process.exit(1);
  }
}

// Start the tests
runTests();

