const http = require('http');
const app = require('./app');

// Create a simple test function
function test(description, asyncFn) {
  console.log(`\nRunning test: ${description}`);
  try {
    const result = asyncFn();
    if (result && result.then) {
      result.catch(err => {
        console.log('❌ Test failed:', err.message || err);
        process.exit(1);
      });
    }
  } catch (err) {
    console.log('❌ Test failed:', err.message || err);
    process.exit(1);
  }
}

// Assertion function
function assert(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

// Test the app by making actual HTTP requests
(async function runTests() {
  // Create server
  const server = app.listen(0); // Use random port
  const port = server.address().port;

  try {
    // Test 1: Happy path - /users endpoint returns correct status and data
    test('Happy path: /users returns 200 and user data', async () => {
      const response = await makeRequest(port, '/users', 'GET');
      assert(response.statusCode === 200, `Expected status 200, got ${response.statusCode}`);
      assert(Array.isArray(response.body), 'Expected response body to be an array');
      assert(response.body.length === 2, `Expected 2 users, got ${response.body.length}`);
      assert(response.body[0].name === 'Alice', 'Expected first user to be Alice');
      assert(response.body[1].name === 'Bob', 'Expected second user to be Bob');
      console.log('✅ Happy path test passed');
    });

    // Test 2: Response format/schema validation
    test('Response format matches expected schema', async () => {
      const response = await makeRequest(port, '/users', 'GET');
      const user = response.body[0];

      // Check required properties and their types
      assert(typeof user.id === 'number', 'User id should be a number');
      assert(typeof user.name === 'string', 'User name should be a string');
      assert(typeof user.email === 'string', 'User email should be a string');

      // Check email format
      const emailRegex = /^[^@]+@[^@]+\.[^@]+$/;
      assert(emailRegex.test(user.email), `Invalid email format: ${user.email}`);

      console.log('✅ Schema validation test passed');
    });

    // Test 3: Error handling - non-existent endpoint
    test('Error handling: non-existent endpoint returns 404', async () => {
      const response = await makeRequest(port, '/non-existent', 'GET');
      assert(response.statusCode === 404, `Expected 404 for non-existent endpoint, got ${response.statusCode}`);
      console.log('✅ Error handling test passed');
    });

    // Wait a moment for all tests to complete
    setTimeout(() => {
      console.log('\n🎉 All tests completed successfully!');
      server.close();
      process.exit(0);
    }, 500);

  } catch (err) {
    console.error('Test suite failed:', err);
    server.close();
    process.exit(1);
  }
})();

// Helper function to make HTTP requests
function makeRequest(port, path, method = 'GET') {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: port,
      path: path,
      method: method
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', chunk => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          const body = data ? JSON.parse(data) : {};
          resolve({ statusCode: res.statusCode, body });
        } catch (err) {
          reject(err);
        }
      });
    });

    req.on('error', reject);
    req.end();
  });
}

