    const originalGetUsers = app._router.stack.find(layer => 
      layer.route?.path === '/users' && layer.route?.methods.get
    );

    // Replace the route handler to throw an error
    app.get('/users', (req, res) => {
      throw new Error('Simulated server error');
    });

    const response = await request(app).get('/users').send();

    // Expect 500 status for server error
    expect(response.status).toBe(500);
    expect(response.body).toEqual({ error: 'Internal Server Error' });

    // Restore the original handler
    app._router.stack.forEach((layer, index) => {
      if (layer === originalGetUsers) {
        app._router.stack[index] = originalGetUsers;
      }
    });

    // Restore console.error
    consoleErrorSpy.mockRestore();
  });

  // Test response format matches expected schema
  test('returns users with correct schema', async () => {
    const response = await request(app).get('/users').send();

    expect(response.status).toBe(200);

    // Validate each user object matches the expected schema
    response.body.forEach(user => {
      expect(user).toMatchObject(expectedUserSchema);

      // Extra validation for email format (simple check)
      expect(user.email).toMatch(/^\S+@\S+\.\S+$/);
    });
  });
